/**
 * Unit tests for Reporter.noMoreInteractionsWanted.
 * Note: Since Reporter is an internal Mockito class and its methods often depend on 
 * complex internal state/static helpers like 'join', we mock the dependency parameters 
 * to trigger the logic and verify the exception behavior.
 */
public class Reporter_noMoreInteractionsWanted_TriageGen2Test {

    @Test
    public void testNoMoreInteractionsWantedThrowsExceptionWithCorrectMessage() {
        // Arrange
        Reporter reporter = new Reporter();

        // Mock the undesired invocation
        Invocation undesired = mock(Invocation.class);
        String mockName = "myMock";
        Location undesiredLocation = mock(Location.class);

        // We need to mock the behavior of undesired to satisfy the method logic
        // The method calls: undesired.getMock() and undesired.getLocation()
        // Note: In actual Mockito, getMock() might return an Object, but here we treat it as a String for the message
        // However, since we can't easily mock the internal 'join' or 'ScenarioPrinter' without PowerMock,
        // we focus on ensuring the method executes the path that throws the exception.

        // Because undesired.getMock() is used in string concatenation, we need it to not return null if possible,
        // or just accept that the exception will be thrown.
        // We use a real mock for the invocation to satisfy the type requirements.

        // To simulate the behavior effectively in a standard JUnit environment:
        // We assume undesired.getMock() returns a String (or toString() is called)
        // and undesired.getLocation() returns a Location.

        // Since we cannot easily mock the final 'join' method or 'ScenarioPrinter' inside the method 
        // without heavy instrumentation, we verify the exception type and the fact that it contains 
        // parts of our input.

        List<VerificationAwareInvocation> invocations = Collections.emptyList();

        // Act & Assert
        try {
            // We use a custom mock to control the return values
            Invocation strictUndesired = new Invocation() {
                @Override
                public Object getMock() {
                    return mockName;
                }

                @Override
                public Location getLocation() {
                    return undesiredLocation;
                }

                @Override
                public Object getInvocation() {
                    return null;
                }

                @Override
                public Object getArguments() {
                    return null;
                }

                @Override
                public Object getStubbing() {
                    return null;
                }

                @Override
                public boolean isVetoed() {
                    return false;
                }
            };

            reporter.noMoreInteractionsWanted(strictUndesired, invocations);
        } catch (NoInteractionsWanted e) {
            String message = e.getMessage();
            assertTrue("Message should contain the header", message.contains("No interactions wanted here:"));
            assertTrue("Message should contain the mock name", message.contains(mockName));
        }
    }

    @Test(expected = NoInteractionsWanted.class)
    public void testNoMoreInteractionsWantedThrowsExceptionWhenInvocationsEmpty() {
        // Arrange
        Reporter reporter = new Reporter();
        Invocation undesired = mock(Invocation.class);
        List<VerificationAwareInvocation> invocations = Collections.emptyList();

        // Act
        reporter.noMoreInteractionsWanted(undesired, invocations);

        // Assert via expected annotation
    }
}
